#!/usr/bin/env node

// [PACKAGING] Removes debug artifacts (sourcemaps, .d.ts, test fixtures) from
// apps/{ui,backend}/dist before electron-builder packs them into app.asar.
//
// Sourcemaps are intentionally generated by vite (`sourcemap: "hidden"`) and
// tsc (`sourceMap: true`) for local crash symbolication, but shipping them to
// every end user inflates the asar by ~87 MB. Sourcemaps are MOVED to
// `release/dist-debug/<target>/` so a developer can still apply them locally
// (`npx source-map-cli apply ...`) — only declarations / test files are deleted
// outright since they have no symbolication value.
//
// IMPORTANT: This script must run AFTER `clean:release`, because the debug
// archive lives inside `release/`. We deliberately stage there because the
// `release/` directory is electron-builder's own `directories.output`, which
// it never walks back into when packing — verified empirically: `!release/**`
// is the only project-root negative pattern electron-builder reliably honors.

const fs = require("fs");
const path = require("path");

const repoRoot = path.resolve(__dirname, "..");

const TARGETS = [
  { name: "ui", dist: path.join(repoRoot, "apps", "ui", "dist") },
  { name: "backend", dist: path.join(repoRoot, "apps", "backend", "dist") },
];

const debugRoot = path.join(repoRoot, "release", "dist-debug");

const MOVE_SUFFIXES = [".js.map", ".mjs.map", ".cjs.map"];
const DELETE_SUFFIXES = [
  ".d.ts.map",
  ".d.cts.map",
  ".d.mts.map",
  ".d.ts",
  ".d.cts",
  ".d.mts",
  ".test.js",
  ".spec.js",
  ".test.cjs",
  ".spec.cjs",
  ".test.mjs",
  ".spec.mjs",
];

function classify(file) {
  const base = path.basename(file);
  for (const suffix of DELETE_SUFFIXES) {
    if (base.endsWith(suffix)) return "delete";
  }
  for (const suffix of MOVE_SUFFIXES) {
    if (base.endsWith(suffix)) return "move";
  }
  return null;
}

function* walk(dir) {
  if (!fs.existsSync(dir)) return;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else if (entry.isFile()) yield full;
  }
}

function ensureDir(dir) {
  fs.mkdirSync(dir, { recursive: true });
}

let movedCount = 0;
let movedBytes = 0;
let deletedCount = 0;
let deletedBytes = 0;

if (fs.existsSync(debugRoot)) {
  fs.rmSync(debugRoot, { recursive: true, force: true });
}

for (const target of TARGETS) {
  for (const file of walk(target.dist)) {
    const action = classify(file);
    if (!action) continue;
    const stat = fs.statSync(file);
    if (action === "move") {
      const rel = path.relative(target.dist, file);
      const dest = path.join(debugRoot, target.name, rel);
      ensureDir(path.dirname(dest));
      fs.renameSync(file, dest);
      movedCount++;
      movedBytes += stat.size;
    } else {
      fs.unlinkSync(file);
      deletedCount++;
      deletedBytes += stat.size;
    }
  }
}

const moveMb = (movedBytes / (1024 * 1024)).toFixed(2);
const delMb = (deletedBytes / (1024 * 1024)).toFixed(2);
console.log(
  `[strip-packaging] archived ${movedCount} sourcemaps (${moveMb} MB) -> dist-debug/, deleted ${deletedCount} type/test artifacts (${delMb} MB)`,
);
